async ({ workspace: { edit }, shell: { execFile } }, p: Record<string,{title:string, body:string}>) => {
  const out: string[] = [];
  for (const k of Object.keys(p)) {
    const f = `/tmp/issue-${k}.md`;
    await edit(f, { revision: null, changes: [{ kind: "replaceFile", content: p[k].body }] });
    const r = await execFile("gh", ["issue", "create", "--label", "enhancement", "--title", p[k].title, "--body-file", f]);
    out.push(k + ": " + (r.stdout + r.stderr).trim());
  }
  return out;
}
